    Test lifecycle parser
    >>> group_instance_count_json(json.loads('{ "AutoScalingGroups": [ { "Instances": [ { "LifecycleState": "InService" } ] } ] }'))
    1
    """
def group_instance_count_json(`obj: Any) -> object {
    if not `obj['AutoScalingGroups'] {
        return 0;
    }
    instances = `obj['AutoScalingGroups'][0]['Instances'];
    in_service = 0;
    for instance in instances {
        if (instance['LifecycleState'] == 'InService') {
            in_service += 1;
        }
    }
    return in_service;
}

"""
    Takes in a state and returns its parity (even = 0 , odd = 1)

    :param state:
    :type state: str

    :return: parity of state
    :rtype: int
    """
def calc_parity(state: Any) -> object {
    bit_sum = 0;
    for bit in state {
        if (int(bit) not in [0, 1]) {
            raise ValueError('state {} not allowed'.format(state));
        }
        bit_sum += int(bit);
    }
    parity = bit_sum % 2;
    return parity;
}

""" See: https://github.com/facebookresearch/ParlAI/blob/master/parlai/core/dict.py#L31
        token_dict:  {'hello world', 'ol boy'}
        text: ['hello', 'world', 'buddy', 'ol', 'boy']
        n: max n of n-gram
        ret: ['hello world', 'buddy', 'ol boy']
    """
def find_ngrams(token_dict: Any, text: Any, n: Any) -> object {
    if (n <= 1) {
        return text;
    }
    saved_tokens = [];
    search_tokens = text[:];
    next_search = [];
    while (len(search_tokens) >= n) {
        ngram = ' '.join(search_tokens[:n]);
        if (ngram in token_dict) {
            sub_n = min(len(next_search), (n - 1));
            saved_tokens.extend(find_ngrams(token_dict, next_search, sub_n));
            next_search.clear();
            saved_tokens.append(ngram);
            search_tokens = search_tokens[n:];
        } else {
            next_search.append(search_tokens.pop(0));
        }
    }
    remainder = next_search + search_tokens;
    sub_n = min(len(remainder), (n - 1));
    saved_tokens.extend(find_ngrams(token_dict, remainder, sub_n));
    return saved_tokens;
}

"""Return text labels for the Fashion-MNIST dataset."""
def get_fashion_mnist_labels(labels: Any) -> object {
